export const DUPLEX_FACADES: Record<string, DuplexFacade[]> = {
  Alabaster: SINGLE_STOREY_DUPLEX_FACADES("alabaster"),
  Cayenne: GARAGE_INSIDE_FACADES("cayenne"),
  Maize: GARAGE_INSIDE_FACADES("maize"),
  Magnolia: GARAGE_OUTSIDE_FACADES("magnolia"),
  Raven: GARAGE_OUTSIDE_FACADES("raven"),
  Teal: CORNER_DUPLEX_FACADES("teal"),
  Wisteria: [
    ...DUAL_LIVING_FACADES("wisteria"),
    ...CORNER_DUPLEX_FACADES("wisteria"),
    ...SINGLE_STOREY_DUPLEX_FACADES("wisteria"),
  ],
};

/** Price-list spellings that differ from the website's design family names. */
const FAMILY_ALIASES: Record<string, string> = {
  maize: "Maize",
  raven: "Raven",
  magnolia: "Magnolia",
  teal: "Teal",
  wisteria: "Wisteria",
  alabaster: "Alabaster",
  cayene: "Cayenne",
  cayenne: "Cayenne",
};

/** The duplex facades published for a dual-occupancy design name, e.g. "Maize 43" or "Teal 29 Corner Lot - TD". */
export function duplexFacadesForDesign(designName: string): DuplexFacade[] {
  const norm = designName.trim();
  const lower = norm.toLowerCase();
  const family = lower.split(/[^a-z]/)[0];
  const key =
    FAMILY_ALIASES[family] ?? Object.keys(DUPLEX_FACADES).find((k) => k.toLowerCase() === family);
  if (!key) return [];

  // Corner Lot check (e.g. "Teal 29 Corner Lot - TD", "Wisteria 29 Corner Lot - TD")
  if (lower.includes("corner")) {
    return CORNER_DUPLEX_FACADES(family);
  }

  // Wisteria specific design variations
  if (key === "Wisteria") {
    const sizeMatch = designName.match(/\b\d+\b/);
    const size = sizeMatch ? Number(sizeMatch[0]) : 0;
    // If it's a Traditional Duplex (TD), e.g. Wisteria 32 - TD (single-storey duplex)
    if (/\btd\b/i.test(norm) || size >= 30) {
      return SINGLE_STOREY_DUPLEX_FACADES("wisteria");
    }
    // Otherwise it's SD / Dual Living (Wisteria 21, 22, 24, 26)
    return DUAL_LIVING_FACADES("wisteria");
  }

  return DUPLEX_FACADES[key] ?? [];
}
